AUGMENTED_REGION_DIM = v2.AUGMENTED_REGION_DIM

MODEL_VARIANTS = ("DualProto_ES", "DualProto_ES_FixKeep")
METHOD_FOR_VARIANT = {
    "DualProto_ES": "Global24__A25__CARE_DualProto_ES",
    "DualProto_ES_FixKeep": "Global24__A25__CARE_DualProto_ES_FixKeep",
}
DIAGNOSTIC_NAMES = (
    "bounded_delta",
    "sparse_logit",
    "diffuse_logit",
    "max_logit",
    "mean_external_distance",
    "mean_internal_distance",
    "mean_shared_commonness",
    "max_local_residual",
)


def seed_everything(seed):
    random.seed(int(seed))
    np.random.seed(int(seed))
    torch.manual_seed(int(seed))
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(int(seed))


def probability_to_logit(probability, epsilon=1e-5):
    probability = np.clip(np.asarray(probability, dtype=np.float64), epsilon, 1.0 - epsilon)
    return np.log(probability / (1.0 - probability)).astype(np.float32)


def inner_oof_joint_s7(
    rows,
    labels,
    source_s7,
    compact_by_sha,
    compact_schema,
    original_names,
    folds,
    split_seed,
    model_seed,
):
    """Strict cross-fitted backbone probabilities for correction training."""
    labels = np.asarray(labels, dtype=np.int64)
    result = np.full(len(labels), np.nan, dtype=np.float64)
    splitter = StratifiedKFold(
        n_splits=int(folds), shuffle=True, random_state=int(split_seed)
    )
    for inner_fold, (fit_index, val_index) in enumerate(
        splitter.split(np.zeros(len(labels)), labels), start=1
    ):
        fit_rows = [rows[index] for index in fit_index]
        val_rows = [rows[index] for index in val_index]
        x_fit, x_val, names = audit.compact_matrix_variant(
            VARIANT,
            fit_rows,
            val_rows,
            compact_by_sha,
            compact_schema,
            original_names,
        )
        global_index, _ = evidence.split_view_indices(names)
        result[val_index] = g24.fit_joint_view(
            x_fit,
            x_val,
            source_s7[fit_index],
            source_s7[val_index],
            labels[fit_index],
            global_index,
            int(model_seed) + inner_fold,
        )
    if np.any(~np.isfinite(result)):
        raise RuntimeError("incomplete inner OOF Joint-S7 probabilities")
    return result


def fit_scaled_dualproto_bags(train_bags, test_bags, labels, args, seed):
    mean, std = care_v1.fit_equal_apk_scaler(
        train_bags, np.arange(len(train_bags), dtype=np.int64)
    )
    scaled_train = [
        (np.asarray(bag, dtype=np.float32) - mean) / std
        for bag in train_bags
    ]
    scaled_test = [
        (np.asarray(bag, dtype=np.float32) - mean) / std
        for bag in test_bags
    ]
    state = v2.fit_prototype_state(scaled_train, labels, args, int(seed))
    augmented_train, train_summary = v2.augment_bags(
        scaled_train, state, "JointDualPrototype", args
    )
    augmented_test, test_summary = v2.augment_bags(
        scaled_test, state, "JointDualPrototype", args
    )
    audit_row = {
        "region_scaler_zero_std_n": int(np.sum(std == 1.0)),
        "shared_prototype_n": int(state["shared_k"]),
        "benign_prototype_n": int(state["benign_k"]),
        "sampled_balanced_region_n": int(state["sampled_balanced_n"]),
        "sampled_benign_region_n": int(state["sampled_benign_n"]),
        "shared_commonness_mean": float(np.mean(state["commonness"])),
        "shared_commonness_max": float(np.max(state["commonness"])),
        "external_distance_scale": float(state["external_scale"]),
        "train_external_mean": float(np.mean(train_summary[:, 0])),
        "test_external_mean": float(np.mean(test_summary[:, 0])),
        "train_internal_mean": float(np.mean(train_summary[:, 1])),
        "test_internal_mean": float(np.mean(test_summary[:, 1])),
        "train_commonness_mean": float(np.mean(train_summary[:, 2])),
        "test_commonness_mean": float(np.mean(test_summary[:, 2])),
    }
    return augmented_train, augmented_test, audit_row


class BoundedDualPrototypeEvidence(nn.Module):
    def __init__(self, global_dim, args):
        super().__init__()
        self.sparse_fraction = float(args.sparse_fraction)
        self.max_delta = float(args.max_delta)
        self.region_encoder = nn.Sequential(
            nn.Linear(AUGMENTED_REGION_DIM, args.hidden_dim),
            nn.ReLU(),
            nn.Dropout(float(args.dropout)),
            nn.Linear(args.hidden_dim, args.embedding_dim),
            nn.ReLU(),
        )
        self.instance_head = nn.Linear(args.embedding_dim, 1)
        fused_dim = global_dim + 1 + 2 * args.embedding_dim + 3 + v2.PROTOTYPE_DIM
        self.delta_head = nn.Sequential(
            nn.Linear(fused_dim, args.hidden_dim),
            nn.ReLU(),
            nn.Dropout(float(args.dropout)),
            nn.Linear(args.hidden_dim, 1),
        )

    def forward(self, global_features, base_logit, regions):
        embedding = self.region_encoder(regions)
        instance_logit = self.instance_head(embedding).reshape(-1)
        k = max(1, int(math.ceil(len(instance_logit) * self.sparse_fraction)))
        top_values, top_index = torch.topk(instance_logit, k=k, largest=True)
        sparse_embedding = torch.mean(embedding[top_index], dim=0)
        diffuse_embedding = torch.mean(embedding, dim=0)
        pooled_logits = torch.stack([
            torch.mean(top_values),
            torch.mean(instance_logit),
            torch.max(instance_logit),
        ])
        prototype_summary = torch.stack([
            torch.mean(regions[:, -4]),
            torch.mean(regions[:, -3]),
            torch.mean(regions[:, -2]),
            torch.max(regions[:, -1]),
        ])
        fused = torch.cat([
            global_features.reshape(-1),
            base_logit.reshape(1),
            sparse_embedding,
            diffuse_embedding,
            pooled_logits,
            prototype_summary,
        ])
        raw_delta = self.delta_head(fused).reshape(())
        bounded_delta = self.max_delta * torch.tanh(raw_delta)
        final_logit = base_logit.reshape(()) + bounded_delta
        diagnostic = torch.cat([bounded_delta.reshape(1), pooled_logits, prototype_summary])
        return final_logit, diagnostic


def fixkeep_weights(labels, base_probability, variant, args):
    labels = np.asarray(labels, dtype=np.int64)
    base_prediction = np.asarray(base_probability) >= 0.5
    base_correct = base_prediction == labels
    if variant == "DualProto_ES":
        weights = np.ones(len(labels), dtype=np.float32)
    elif variant == "DualProto_ES_FixKeep":
        weights = np.where(
            base_correct, float(args.keep_weight), float(args.fix_weight)
        ).astype(np.float32)
        # Preserve class mass so the asymmetric objective does not alter the
        # benign/malware prior merely because one class has more base errors.
        for label in (0, 1):
            selected = labels == label
            weights[selected] *= float(np.sum(selected)) / float(np.sum(weights[selected]))
    else:
        raise ValueError("unknown variant: " + str(variant))
    return weights, base_correct


def batch_loss(
    logits,
    labels,
    weights,
    base_probabilities,
    base_correct,
    variant,
    args,
):
    element = nn.functional.binary_cross_entropy_with_logits(
        logits, labels, reduction="none"
    )
    loss = torch.sum(element * weights) / torch.sum(weights)
    if variant == "DualProto_ES_FixKeep" and float(args.keep_consistency) > 0.0:
        selected = base_correct
        if bool(torch.any(selected)):
            final_probability = torch.sigmoid(logits[selected])
            keep_loss = torch.mean(torch.square(
                final_probability - base_probabilities[selected]
            ))
            loss = loss + float(args.keep_consistency) * keep_loss
    return loss


def train_fixed_epochs(
    global_values,
    base_probability,
    bags,
    labels,
    variant,
    epochs,
    args,
    device,
    seed,
):
    seed_everything(seed)
    model = BoundedDualPrototypeEvidence(global_values.shape[1], args).to(device)
    optimizer = torch.optim.Adam(
        model.parameters(), lr=args.learning_rate, weight_decay=args.weight_decay
    )
    global_tensor = torch.as_tensor(global_values, dtype=torch.float32, device=device)
    base_prob_tensor = torch.as_tensor(base_probability, dtype=torch.float32, device=device)
    base_logit_tensor = torch.as_tensor(
        probability_to_logit(base_probability), dtype=torch.float32, device=device
    )
    label_tensor = torch.as_tensor(labels, dtype=torch.float32, device=device)
    weights, base_correct = fixkeep_weights(labels, base_probability, variant, args)
    weight_tensor = torch.as_tensor(weights, dtype=torch.float32, device=device)
    correct_tensor = torch.as_tensor(base_correct, dtype=torch.bool, device=device)
    bag_tensors = [
        torch.as_tensor(value, dtype=torch.float32, device=device) for value in bags
    ]
    rng = np.random.RandomState(int(seed) + 3303)
    final_loss = float("nan")
    model.train()
    for _ in range(int(epochs)):
        order = rng.permutation(len(labels))
        epoch_loss = 0.0
        for start in range(0, len(labels), int(args.batch_size)):
            batch = order[start:start + int(args.batch_size)]
            optimizer.zero_grad(set_to_none=True)
            logits = []
            for index in batch:
                logit, _ = model(
                    global_tensor[int(index)],
                    base_logit_tensor[int(index)],
                    bag_tensors[int(index)],
                )
                logits.append(logit)
            stacked = torch.stack(logits)
            batch_index = torch.as_tensor(batch, dtype=torch.long, device=device)
            loss = batch_loss(
                stacked,
                label_tensor[batch_index],
                weight_tensor[batch_index],
                base_prob_tensor[batch_index],
                correct_tensor[batch_index],
                variant,
                args,
            )
            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), args.grad_clip)
            optimizer.step()
            epoch_loss += float(loss.detach().cpu()) * len(batch)
        final_loss = epoch_loss / len(labels)
    return model, final_loss, bag_tensors


def evaluate_loss(model, global_values, base_probability, bags, labels, variant, args, device):
    global_tensor = torch.as_tensor(global_values, dtype=torch.float32, device=device)
    base_prob_tensor = torch.as_tensor(base_probability, dtype=torch.float32, device=device)
    base_logit_tensor = torch.as_tensor(
        probability_to_logit(base_probability), dtype=torch.float32, device=device
    )
    label_tensor = torch.as_tensor(labels, dtype=torch.float32, device=device)
    weights, base_correct = fixkeep_weights(labels, base_probability, variant, args)
    weight_tensor = torch.as_tensor(weights, dtype=torch.float32, device=device)
    correct_tensor = torch.as_tensor(base_correct, dtype=torch.bool, device=device)
    logits = []
    model.eval()
    with torch.no_grad():
        for index, bag in enumerate(bags):
            bag_tensor = torch.as_tensor(bag, dtype=torch.float32, device=device)
            logit, _ = model(global_tensor[index], base_logit_tensor[index], bag_tensor)
            logits.append(logit)
        stacked = torch.stack(logits)
        loss = batch_loss(
            stacked,
            label_tensor,
            weight_tensor,
            base_prob_tensor,
            correct_tensor,
            variant,
            args,
        )
    return float(loss.cpu())


def select_epochs(
    global_values,
    base_probability,
    raw_bags,
    labels,
    variant,
    args,
    device,
    seed,
):
    indices = np.arange(len(labels), dtype=np.int64)
    fit_index, val_index = train_test_split(
        indices,
        test_size=float(args.early_stop_fraction),
        stratify=np.asarray(labels),
        random_state=int(seed) + 404,
    )
    fit_raw = [raw_bags[index] for index in fit_index]
    val_raw = [raw_bags[index] for index in val_index]
    fit_bags, val_bags, _ = fit_scaled_dualproto_bags(
        fit_raw, val_raw, np.asarray(labels)[fit_index], args, int(seed) + 505
    )
    seed_everything(seed)
    model = BoundedDualPrototypeEvidence(global_values.shape[1], args).to(device)
    optimizer = torch.optim.Adam(
        model.parameters(), lr=args.learning_rate, weight_decay=args.weight_decay
    )
    fit_global = torch.as_tensor(global_values[fit_index], dtype=torch.float32, device=device)
    fit_base_prob = torch.as_tensor(base_probability[fit_index], dtype=torch.float32, device=device)
    fit_base_logit = torch.as_tensor(
        probability_to_logit(base_probability[fit_index]), dtype=torch.float32, device=device
    )
    fit_labels = torch.as_tensor(np.asarray(labels)[fit_index], dtype=torch.float32, device=device)
    fit_weights_np, fit_correct_np = fixkeep_weights(
        np.asarray(labels)[fit_index], base_probability[fit_index], variant, args
    )
    fit_weights = torch.as_tensor(fit_weights_np, dtype=torch.float32, device=device)
    fit_correct = torch.as_tensor(fit_correct_np, dtype=torch.bool, device=device)
    fit_bag_tensors = [
        torch.as_tensor(value, dtype=torch.float32, device=device) for value in fit_bags
    ]
    rng = np.random.RandomState(int(seed) + 606)
    best_epoch = 1
    best_loss = float("inf")
    stale = 0
    history = []
    for epoch in range(1, int(args.max_epochs) + 1):
        model.train()
        order = rng.permutation(len(fit_index))
        for start in range(0, len(fit_index), int(args.batch_size)):
            batch = order[start:start + int(args.batch_size)]
            optimizer.zero_grad(set_to_none=True)
            logits = []
            for local_index in batch:
                logit, _ = model(
                    fit_global[int(local_index)],
                    fit_base_logit[int(local_index)],
                    fit_bag_tensors[int(local_index)],
                )
                logits.append(logit)
            batch_index = torch.as_tensor(batch, dtype=torch.long, device=device)
            loss = batch_loss(
                torch.stack(logits),
                fit_labels[batch_index],
                fit_weights[batch_index],
                fit_base_prob[batch_index],
                fit_correct[batch_index],
                variant,
                args,
            )
            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), args.grad_clip)
            optimizer.step()
        val_loss = evaluate_loss(
            model,
            global_values[val_index],
            base_probability[val_index],
            val_bags,
            np.asarray(labels)[val_index],
            variant,
            args,
            device,
        )
        history.append(float(val_loss))
        if val_loss < best_loss - float(args.early_stop_min_delta):
            best_loss = float(val_loss)
            best_epoch = int(epoch)
            stale = 0
        else:
            stale += 1
        if stale >= int(args.early_stop_patience):
            break
    del model, fit_bag_tensors
    if device.type == "cuda":
        torch.cuda.empty_cache()
    return best_epoch, best_loss, history, int(len(fit_index)), int(len(val_index))


def predict_model(model, global_values, base_probability, bags, device):
    global_tensor = torch.as_tensor(global_values, dtype=torch.float32, device=device)
    base_logit_tensor = torch.as_tensor(
        probability_to_logit(base_probability), dtype=torch.float32, device=device
    )
    probabilities = []
    diagnostics = []
    model.eval()
    with torch.no_grad():
        for index, bag in enumerate(bags):
            bag_tensor = torch.as_tensor(bag, dtype=torch.float32, device=device)
            logit, diagnostic = model(
                global_tensor[index], base_logit_tensor[index], bag_tensor
            )
            probabilities.append(float(torch.sigmoid(logit).cpu()))
            diagnostics.append(diagnostic.detach().cpu().numpy())
    return np.asarray(probabilities), np.asarray(diagnostics)


def fit_predict_variant(
    global_train,
    global_test,
    base_train,
    base_test,
    train_bags,
    test_bags,
    labels,
    variant,
    seeds,
    args,
    device,
):
    probabilities = []
    diagnostics = []
    seed_audits = []
    for seed in seeds:
        best_epoch, best_val_loss, history, inner_fit_n, inner_val_n = select_epochs(
            global_train,
            base_train,
            train_bags,
            labels,
            variant,
            args,
            device,
            int(seed),
        )
        augmented_train, augmented_test, prototype_audit = fit_scaled_dualproto_bags(
            train_bags, test_bags, labels, args, int(seed) + 707
        )
        model, final_loss, train_tensors = train_fixed_epochs(
            global_train,
            base_train,
            augmented_train,
            labels,
            variant,
            best_epoch,
            args,
            device,
            int(seed) + 808,
        )
        probability, diagnostic = predict_model(
            model, global_test, base_test, augmented_test, device
        )
        probabilities.append(probability)
        diagnostics.append(diagnostic)
        seed_audits.append({
            "seed": int(seed),
            "selected_epoch": int(best_epoch),
            "best_inner_validation_loss": float(best_val_loss),
            "epochs_evaluated": int(len(history)),
            "inner_fit_n": int(inner_fit_n),
            "inner_validation_n": int(inner_val_n),
            "refit_final_loss": float(final_loss),
            "inner_validation_loss_history": [float(value) for value in history],
            **prototype_audit,
        })
        del model, train_tensors
        if device.type == "cuda":
            torch.cuda.empty_cache()
    return (
        np.mean(np.asarray(probabilities), axis=0),
        np.mean(np.asarray(diagnostics), axis=0),
        seed_audits,
    )


def load_source_s7(source_rows, endpoint_cache, args):
    print("Reconstructing source Stats120+PairRaw465...", flush=True)
    source_s3, _ = audit.future.reconstruct_structure(
        source_rows, endpoint_cache, int(audit.exp.ROLE_VOCABULARY_SIZE)
    )
    if source_s3.shape != (len(source_rows), 585):
        raise RuntimeError("bad source S3 shape: " + repr(source_s3.shape))
    source_s7, reference = future_s7.source_s7_from_reference(
        args.source_multiscale_features, source_rows, source_s3
    )
    if source_s7.shape[1] != 1546:
        raise RuntimeError("bad source S7 dimension")
    return source_s7, reference


def add_prediction_columns(output, expert, final, diagnostic, index):
    for variant in MODEL_VARIANTS:
        method = METHOD_FOR_VARIANT[variant]
        output[method + "__expert_prob"] = float(expert[variant][index])
        output[method + "__prob"] = float(final[method][index])
        for column_index, name in enumerate(DIAGNOSTIC_NAMES):
            output[method + "__" + name] = float(
                diagnostic[variant][index, column_index]
            )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--features", type=Path, default=Path("artifacts/p1-features/features.csv"))
    parser.add_argument("--schema", type=Path, default=Path("artifacts/p1-features/feature_schema.json"))
    parser.add_argument("--cache", type=Path, default=Path(
        "artifacts/p25-endpoint-cache-full-cap256/endpoint_centered_tensor_cache.jsonl.gz"
    ))
    parser.add_argument("--p72-oof", type=Path, default=Path(
        "artifacts/p72-verified-dependency-source-ablation/p72_oof_predictions.csv"
    ))
    parser.add_argument("--source-multiscale-features", type=Path, default=Path(
        "artifacts/clipped-intra-inter-structure-ablation-2017-v1-full/multiscale_features.npz"
    ))
    parser.add_argument("--previous-result", type=Path, default=Path(
        "artifacts/global24-a25-route-conditioned-joints7-v1-full"
    ))
    parser.add_argument("--region-cache", type=Path, default=Path(
        "artifacts/care-local-region-cache-v1/regions_2017_2021.npz"
    ))
    parser.add_argument("--rebuild-region-cache", action="store_true")
    parser.add_argument("--years", default="2018,2019,2020,2021")
    parser.add_argument("--seeds", default="0")
    parser.add_argument("--inner-folds", type=int, default=4)
    parser.add_argument("--split-seed", type=int, default=20260828)
    parser.add_argument("--max-epochs", type=int, default=30)
    parser.add_argument("--early-stop-fraction", type=float, default=0.18)
    parser.add_argument("--early-stop-patience", type=int, default=5)
    parser.add_argument("--early-stop-min-delta", type=float, default=1e-4)
    parser.add_argument("--batch-size", type=int, default=16)
    parser.add_argument("--hidden-dim", type=int, default=32)
    parser.add_argument("--embedding-dim", type=int, default=12)
    parser.add_argument("--sparse-fraction", type=float, default=0.10)
    parser.add_argument("--dropout", type=float, default=0.20)
    parser.add_argument("--learning-rate", type=float, default=8e-4)
    parser.add_argument("--weight-decay", type=float, default=5e-4)
    parser.add_argument("--grad-clip", type=float, default=5.0)
    parser.add_argument("--max-delta", type=float, default=1.0)
    parser.add_argument("--keep-weight", type=float, default=2.0)
    parser.add_argument("--fix-weight", type=float, default=1.0)
